package net.wtworkshop.beeblock.gametest;
import java.util.*;import net.minecraft.gametest.framework.*;import net.minecraft.world.item.*;import net.minecraft.world.inventory.ClickType;import net.minecraft.world.level.GameType;import net.minecraft.world.entity.EntityType;import net.minecraft.core.BlockPos;import net.minecraft.world.InteractionHand;import net.minecraft.world.effect.*;import net.neoforged.neoforge.gametest.*;import net.wtworkshop.tool.*;import net.wtworkshop.station.*;import net.wtworkshop.beeblock.*;
@GameTestHolder("wt_workshop") @PrefixGameTestTemplate(false)
public final class BeeTests {
 private static StationLogic.Outcome apply(GameTestHelper h,ItemStack tool,ItemStack ingredient){return StationLogic.compute(List.of(ItemStack.EMPTY,ItemStack.EMPTY,ItemStack.EMPTY,tool,ingredient),h.getLevel());}
 private static ItemStack sword(String id){return WorkshopTool.create(ToolType.SWORD,ToolData.of("iron","wood","string").withAddonSlot(id,Modifier.Slot.ABILITY).withModifierAdded(id));}
 @GameTest(template="empty") public static void addonRecipesSlotsAndPartialProgress(GameTestHelper h){var tool=WorkshopTool.create(ToolType.PICKAXE,ToolData.of("iron","wood","string"));var wax=apply(h,tool,new ItemStack(Items.HONEYCOMB,8));h.assertTrue(wax.success()&&wax.consume()[3]==1&&wax.consume()[4]==8&&WorkshopTool.data(wax.result()).modifierLevel(BeeWorkshop.WAXED)==1&&WorkshopTool.stats(wax.result()).usedUpgrades()==1,"Wax application failed");h.assertTrue(!apply(h,tool,new ItemStack(Items.HONEY_BOTTLE,8)).success(),"Mining pick accepted weapon modifier");var s=WorkshopTool.create(ToolType.SWORD,ToolData.of("iron","wood","string"));var partial=apply(h,s,new ItemStack(Items.HONEY_BOTTLE,3));h.assertTrue(partial.success()&&WorkshopTool.data(partial.result()).progressOf(BeeWorkshop.HONEYBOUND)==3&&WorkshopTool.stats(partial.result()).usedAbilities()==0,"Partial honey progress wrong");var done=apply(h,partial.result(),new ItemStack(Items.HONEY_BOTTLE,5));h.assertTrue(done.success()&&WorkshopTool.stats(done.result()).usedAbilities()==1,"Honey completion wrong");h.assertTrue(!apply(h,done.result(),new ItemStack(Items.HONEY_BOTTLE,8)).success(),"Honey ignored full ability slots");var max=ToolData.of("iron","wood","string");for(int i=0;i<3;i++)max=max.withModifierAdded(BeeWorkshop.WAXED).withAddonSlot(BeeWorkshop.WAXED,Modifier.Slot.UPGRADE);h.assertTrue(!apply(h,WorkshopTool.create(ToolType.AXE,max),new ItemStack(Items.HONEYCOMB,8)).success(),"Wax exceeded cap");h.succeed();}
 @GameTest(template="empty") public static void honeyReturnsBottlesOnceOnPickupAndShift(GameTestHelper h){for(boolean shift:new boolean[]{false,true}){var p=h.makeMockPlayer(GameType.SURVIVAL);var menu=new StationMenu(1,p.getInventory());menu.getSlot(4).set(WorkshopTool.create(ToolType.SWORD,ToolData.of("iron","wood","string")));menu.getSlot(5).set(new ItemStack(Items.HONEY_BOTTLE,8));if(shift)menu.quickMoveStack(p,0);else menu.clicked(0,0,ClickType.PICKUP,p);int bottles=p.getInventory().items.stream().filter(s->s.is(Items.GLASS_BOTTLE)).mapToInt(ItemStack::getCount).sum();h.assertTrue(bottles==8&&menu.getSlot(4).getItem().isEmpty()&&menu.getSlot(5).getItem().isEmpty(),"Bottles missing or duplicated: "+bottles);}h.succeed();}
 @GameTest(template="empty") public static void waxReducesActualWear(GameTestHelper h){var p=h.makeMockPlayer(GameType.SURVIVAL);var base=WorkshopTool.create(ToolType.PICKAXE,ToolData.of("iron","wood","string"));var wax=apply(h,base,new ItemStack(Items.HONEYCOMB,8)).result();var item=(WorkshopTool)base.getItem();int ordinary=0,protectedWear=0;p.getRandom().setSeed(12345);for(int i=0;i<10000;i++)ordinary+=item.damageItem(base,1,p,b->{});p.getRandom().setSeed(12345);for(int i=0;i<10000;i++)protectedWear+=item.damageItem(wax,1,p,b->{});h.assertTrue(protectedWear<ordinary-100&&protectedWear>0,"Wax did not reduce real durability consumption");h.succeed();}
 @GameTest(template="empty") public static void honeyRequiresHealthDamageAndRespectsCooldown(GameTestHelper h){var p=h.makeMockServerPlayerInLevel();p.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);p.setItemInHand(InteractionHand.MAIN_HAND,sword(BeeWorkshop.HONEYBOUND));var shielded=h.spawn(EntityType.ZOMBIE,new BlockPos(1,1,1));shielded.addEffect(new MobEffectInstance(MobEffects.ABSORPTION,200,4));shielded.hurt(p.damageSources().playerAttack(p),4);h.assertTrue(!shielded.hasEffect(MobEffects.MOVEMENT_SLOWDOWN),"Absorption triggered honey");var target=h.spawn(EntityType.ZOMBIE,new BlockPos(1,1,1));target.hurt(p.damageSources().playerAttack(p),4);h.assertTrue(target.hasEffect(MobEffects.MOVEMENT_SLOWDOWN)&&target.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getAmplifier()==0,"Honey hit did not slow target");var other=h.spawn(EntityType.ZOMBIE,new BlockPos(1,1,1));other.hurt(p.damageSources().playerAttack(p),4);h.assertTrue(!other.hasEffect(MobEffects.MOVEMENT_SLOWDOWN),"Cooldown ignored");h.runAfterDelay(21,()->{var fresh=h.spawn(EntityType.ZOMBIE,new BlockPos(1,1,1));fresh.hurt(p.damageSources().playerAttack(p),4);h.assertTrue(fresh.hasEffect(MobEffects.MOVEMENT_SLOWDOWN),"Cooldown never expired");h.succeed();});}
 @GameTest(template="empty") public static void forestryIngredientsApplyWhenInstalled(GameTestHelper h){if(net.neoforged.fml.ModList.get().isLoaded("forestry")){var items=net.minecraft.core.registries.BuiltInRegistries.ITEM;var wax=items.get(net.minecraft.resources.ResourceLocation.parse("forestry:beeswax"));var honey=items.get(net.minecraft.resources.ResourceLocation.parse("forestry:honey_drop"));h.assertTrue(wax!=Items.AIR&&honey!=Items.AIR,"Forestry ingredient IDs missing");var tool=WorkshopTool.create(ToolType.SWORD,ToolData.of("iron","wood","string"));h.assertTrue(apply(h,tool,new ItemStack(wax,8)).success()&&apply(h,tool,new ItemStack(honey,8)).success(),"Forestry tags not accepted");}h.succeed();}
}
